import { useContext } from 'react';
import { MappingShapeContent, ShapeSlotsContext } from '../tldraw/shapeSlots';
import type { CanvasDisplayNode } from '../../../../domain/mapping/workspace/canvasDisplayNode';
import './diagramSubtreeControls.css';

/** Controls consume the public DisplayNode capability, never parse source text. */
export function DiagramSubtreeControls(props: {
  nodes: CanvasDisplayNode[]; visibleBoxIds: ReadonlySet<string>;
  cell: { width: number; height: number }; disabled: boolean;
  onCollapse: (nodeId: string, contentNodeId: string, collapsed: boolean) => void;
}) {
  const native = useContext(ShapeSlotsContext);
  if (!props.cell.width || !props.cell.height) return null;
  return <>{props.nodes.flatMap(node => {
    if (node.layout !== 'grid' || node.kind !== 'diagram' || node.expansion === 'collapsed' || !props.visibleBoxIds.has(node.boxId)) return [];
    return node.collapsible.subtrees.filter(target => target.visibleRow !== undefined).map(target => <MappingShapeContent key={`${node.id}:${target.contentNodeId}`} id={node.id}><button type="button" className="mapping-subtree-toggle"
      data-mapping-static-ui data-diagram-canvas-static-ui data-subtree-owner={node.id} data-content-node-id={target.contentNodeId}
      data-subtree-line={target.line} data-visible-row={target.visibleRow}
      disabled={props.disabled} aria-expanded={target.expansion === 'expanded'}
      aria-label={`${target.expansion === 'expanded' ? 'Collapse' : 'Expand'} subtree ${target.label}`}
      title={`${target.expansion === 'expanded' ? 'Collapse' : 'Expand'} ${target.label}`}
      style={{ left: ((native ? 0 : node.geometry.bounds.column) + (target.branchColumn < 0 ? -3 : target.branchColumn)) * props.cell.width,
        top: ((native ? 0 : node.geometry.bounds.row) + target.visibleRow!) * props.cell.height,
        width: props.cell.width * 3, height: props.cell.height }}
      onPointerDown={event => event.stopPropagation()} onDoubleClick={event => event.stopPropagation()}
      onClick={event => { event.stopPropagation(); props.onCollapse(node.id, target.contentNodeId, target.expansion !== 'collapsed'); }}
    >{target.expansion === 'expanded' ? '[-]' : '[+]'}</button></MappingShapeContent>);
  })}</>;
}

import { MappingShapeContent, ShapeSlotsContext } from '../tldraw/shapeSlots';
import { useContext, useLayoutEffect, useRef, useState, type ReactNode } from 'react';
import type { DetailPane, ProjectedPane } from '../../../../domain/mapping/workspace/displayModel';
export function EffectPaneHeader(props: { title: string; eyebrow?: string; metadata?: string; actions?: ReactNode; className?: string }) {
  return <header className={props.className}><div>{props.eyebrow && <span>{props.eyebrow}</span>}<strong title={props.title}>{props.title}</strong></div>
    {props.metadata && <small>{props.metadata}</small>}{props.actions}</header>;
}
/** Shared pane frame: model placement, allocation, measured content, and expansion controls. */
export function DisplayPane(props: {
  node: ProjectedPane | DetailPane; metadata?: string;
  onToggle: () => void; onRemove: () => void;
  actions?: ReactNode; children: ReactNode;
  onMeasure: (id: string, width: number, height: number) => void;
}) {
  const { node } = props;
  const native = useContext(ShapeSlotsContext);
  const expanded = node.expansion === 'expanded';
  const fixed = node.geometryPolicy.sizing === 'fixed';
  const [element, setElement] = useState<HTMLElement | null>(null);
  const measure = useRef(props.onMeasure); measure.current = props.onMeasure;
  useLayoutEffect(() => {
    const el = element; if (!el) return;
    const report = () => measure.current(node.id, el.offsetWidth, el.offsetHeight);
    report(); const observer = new ResizeObserver(report); observer.observe(el);
    return () => observer.disconnect();
  }, [element, node.id]);
  return <MappingShapeContent id={`floating:${node.id}`}><aside ref={setElement} className="selection-effect-frame mapping-poc-companion" data-display-node={node.id}
    data-pane-content={node.kind === 'projection' ? node.content.kind : 'detail'}
    data-projection-id={node.kind === 'projection' ? node.projectionId : undefined} data-mapping-static-ui data-diagram-canvas-static-ui
    onPointerDown={event => { if (!(event.target as Element).closest('.selection-effect-header') || (event.target as Element).closest('button,input,select')) event.stopPropagation(); }}
    style={{ left: native ? 0 : node.position.x, top: native ? 0 : node.position.y, boxSizing: 'border-box',
      width: fixed ? native ? '100%' : node.bounds.width : undefined, height: fixed && expanded ? native ? '100%' : node.bounds.height : undefined }}>
    <EffectPaneHeader className="selection-effect-header" title={node.title} metadata={props.metadata} actions={<>
      {props.actions}
      <button type="button" onClick={props.onToggle} aria-expanded={expanded} aria-label={expanded ? 'Collapse pane' : 'Expand pane'}>{expanded ? '−' : '+'}</button>
      <button type="button" onClick={props.onRemove} aria-label="Close pane">×</button>
    </>} />
    {expanded && <div className="selection-effect-body">{props.children}</div>}
  </aside></MappingShapeContent>;
}

